        public static string GetConnectionString()
        {
            try
            {
                string json = File.ReadAllText("appsettings.json");
                using (JsonDocument doc = JsonDocument.Parse(json))
                {
                    // 1. Leemos la IP
                    string ip = doc.RootElement.GetProperty("ConfiguracioGlobal").GetProperty("IpServidor").GetString();

                    // 2. Leemos la plantilla de Oracle (que tiene un {0})
                    string template = doc.RootElement.GetProperty("ConnectionStrings").GetProperty("OracleTemplate").GetString();

                    // 3. Sustituimos {0} por la IP real
                    return string.Format(template, ip);
                }
            }
            catch (Exception)
            {
                return "";
            }
        }

        // DBSETS Afegeix-los per poder consultar amb EF
        public DbSet<Item> Items { get; set; }
        public DbSet<Producte> Productes { get; set; }
        public DbSet<Componente> Components { get; set; }
        public DbSet<Proveidor> Proveidors { get; set; }
        public DbSet<Municipi> Municipis { get; set; }
        public DbSet<Provincia> Provincies { get; set; }

        //No fem un per unitat de mesura perque es un enum.


        /// <summary>
        /// Metode per configurar el mapeig de les entitats amb les taules de la base de dades Oracle.
        /// </summary>
        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            // --- ITEM (Base) ---
            modelBuilder.Entity<Item>(entity =>
            {
                entity.ToTable("ITEM");
                entity.HasKey(e => e.Codi);
                entity.Property(e => e.Codi).HasColumnName("it_codi");
                entity.Property(e => e.Nom).HasColumnName("it_nom");
                entity.Property(e => e.Descripcio).HasColumnName("it_desc");
                entity.Property(e => e.Stock).HasColumnName("it_stock");
                entity.Property(e => e.Foto).HasColumnName("it_foto");
                entity.Property(e => e.Tipus).HasColumnName("it_tipus");
            });

            // --- PRODUCTE (Herència) ---
            modelBuilder.Entity<Producte>(entity =>
            {
                entity.ToTable("PRODUCTE");
                entity.Property(e => e.Codi).HasColumnName("pr_it_codi");
                entity.Ignore(e => e.Comps);
            });

            // --- COMPONENTE (Herència) ---
            modelBuilder.Entity<Componente>(entity =>
            {
                entity.ToTable("COMPONENTE");
                entity.Property(e => e.Codi).HasColumnName("cm_it_codi");
                entity.Property(e => e.CodiFabricant).HasColumnName("cm_codi_fabricant");
                entity.Property(e => e.PreuMig).HasColumnName("cm_preu_mig");
                entity.Property(e => e.Unitat).HasColumnName("cm_um_codi");
                entity.Ignore(e => e.Proveidors_preu);
            });

            // --- PROVINCIA ---
            modelBuilder.Entity<Provincia>(entity =>
            {
                entity.ToTable("PROVINCIA");
                entity.HasKey(e => e.Codi);
                entity.Property(e => e.Codi).HasColumnName("pr_codi");
                entity.Property(e => e.Nom).HasColumnName("pr_nom");
            });


            // --- MUNICIPI ---
            modelBuilder.Entity<Municipi>(entity =>
            {
                entity.ToTable("MUNICIPI");

                // PK Composta (necessita les propietats C#)
                entity.HasKey(e => new { e.ProvinciaCodi, e.Codi });

                // Mapeig de columnes PK
                entity.Property(e => e.Codi).HasColumnName("mu_codi");
                entity.Property(e => e.ProvinciaCodi).HasColumnName("mu_pr_codi");
                // Mapeig de la resta
                entity.Property(e => e.Nom).HasColumnName("mu_nom");

                // Relació (FK)
                entity.HasOne(e => e.Provincia)
                      .WithMany()
                      .HasForeignKey(e => e.ProvinciaCodi); // Enllaça amb la propietat C#
            });

            // --- PROVEIDOR (Actualitzat) ---
            modelBuilder.Entity<Proveidor>(entity =>
            {
                entity.ToTable("PROVEIDOR");
                entity.HasKey(e => e.Codi);
                entity.Property(e => e.Codi).HasColumnName("pv_codi");

                // Mapeig de la resta de columnes
                entity.Property(e => e.Cif).HasColumnName("pv_CIF");
                entity.Property(e => e.RaoSocial).HasColumnName("pv_rao_social");
                entity.Property(e => e.AdrFacturacio).HasColumnName("pv_linia_adreça_facturacio");
                entity.Property(e => e.Persona_contacte).HasColumnName("pv_persona_contacte");
                entity.Property(e => e.TelfContacte).HasColumnName("pv_telf_contacte");

                // Relació (FK Composta)
                entity.HasOne(e => e.Municipi) // La propietat de navegació C#
                      .WithMany()
                      // Li diem quines columnes FK de la BD ha de fer servir
                      // (Aquestes són ara "Shadow Properties")
                      .HasForeignKey("pv_mu_pr_codi", "pv_mu_codi");
            });

            // La taula UNITATMESURA no és una entitat que EF hagi de gestionar
            // ja que la fem servir com un Enum.
        }

    }//end MyDBContext

